/*建表登记表*/

drop table pbc_col_init_prod_raising_sub;

CREATE TABLE pbc_col_init_prod_raising_sub(
    REGIST_SEQNO 				char(36)     ,
    PROD_ID 					varchar2(50) ,
    PBC_PROD_ID 				varchar2(50) ,
    BUY_PLACE 					varchar2(50) ,
    CUSTOMER_TYPE1 				varchar2(50) ,
    CCY 						char(3) 	 ,
    INIT_RAISING_AMTSUM 		NUMBER(30,2) ,
    INIT_RAISING_AMTSUMCNY 		NUMBER(30,2) ,
    INIT_RAISING_QTY 			NUMBER(30,5) ,
    SEND_STATUS 				varchar2(50) ,
    SUBMIT_TIME 				TIMESTAMP(6) ,
    SUBMIT_FEEDBACK_STATUS 		varchar2(50) ,
    SUMIT_SEQ 					varchar2(20) ,
    STATUS_DATE 				date 		 ,
    PBC_SUBMIT_DEADLINE 		TIMESTAMP(6) ,
    SUBMIT_DEADLINE 			TIMESTAMP(6) ,
    STATUS 						varchar2(50) ,
    CREATE_USER 				varchar2(20) ,
    ORG_CODE 					varchar2(32) ,
    CREATE_DEPT 				varchar2(32) ,
    CREATE_TIME 				TIMESTAMP(6) ,
    UPDATE_USER 				varchar2(20) ,
    UPDATE_TIME 				TIMESTAMP(6) ,
    CONSTRAINT pbc_col_init_prod_raising_sub PRIMARY KEY (REGIST_SEQNO) 
    );
COMMENT ON table  pbc_col_init_prod_raising_sub  						IS 'ZG02资管产品初始募集信息登记表'  				 ;
COMMENT ON COLUMN  pbc_col_init_prod_raising_sub.REGIST_SEQNO           IS '登记序列:主键uuid'                               ;
COMMENT ON COLUMN  pbc_col_init_prod_raising_sub.PROD_ID                 IS '行内产品代码'                                    ;
COMMENT ON COLUMN  pbc_col_init_prod_raising_sub.PBC_PROD_ID             IS '人行产品代码'                                    ;
COMMENT ON COLUMN  pbc_col_init_prod_raising_sub.BUY_PLACE              IS '地区代码:销售区域代码'                           ;
COMMENT ON COLUMN  pbc_col_init_prod_raising_sub.CUSTOMER_TYPE1             IS '客户类型:客户一级类型，枚举值参见CUSTOMER_TYPE1' ;
COMMENT ON COLUMN  pbc_col_init_prod_raising_sub.CCY                 IS '币种代码:币种'                                   ;
COMMENT ON COLUMN  pbc_col_init_prod_raising_sub.INIT_RAISING_AMTSUM             IS '初始募集金额'                                    ;
COMMENT ON COLUMN  pbc_col_init_prod_raising_sub.INIT_RAISING_AMTSUMCNY              IS '初始募集金额折人民币'                            ;
COMMENT ON COLUMN  pbc_col_init_prod_raising_sub.INIT_RAISING_QTY             IS '初始募集份额'                                    ;
COMMENT ON COLUMN  pbc_col_init_prod_raising_sub.SEND_STATUS                 IS '报送状态'                                        ;
COMMENT ON COLUMN  pbc_col_init_prod_raising_sub.SUBMIT_TIME             IS '报送日期'                                        ;
COMMENT ON COLUMN  pbc_col_init_prod_raising_sub.PBC_SUBMIT_DEADLINE              IS '报送反馈状态'                                    ;
